            Describe.Lean(DescribeId.Create("sourceamplitude-true-finite"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianFiniteCandidateModes.sourceAmplitude_true_finite"), H("sourceAmplitude_true_finite"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Exact support reduction of the actual positive source to a finite polynomial."))), DescribeRole.Theorem),
